def verify(root: Path = ROOT) -> list[str]:
    failures: list[str] = []
    version = _active_version(root)
    if not version:
        return ["VERSION.md active baseline is missing or malformed"]

    version_key = _version_key(version)
    package_version = _package_version(version)
    pyproject = _read(root / "pyproject.toml")
    init = _read(root / "src/ultimate_ai_agent/__init__.py")
    readme = _read(root / "README.md")

    if f'version = "{package_version}"' not in pyproject:
        failures.append("pyproject.toml version does not match VERSION.md")
    if f'__version__ = "{package_version}"' not in init:
        failures.append("package __version__ does not match VERSION.md")

    active_import, active_master = _release_packet_paths(version_key)
    active_release_notes = f"docs/release_notes/v{version_key}.md"
    active_gate_plan = f"docs/implementation/foundation_gate_implementation_plan_v{version_key}.md"
    failures.extend(_verify_active_baseline_labels(root, version))
    failures.extend(_verify_operator_runtime_currentness(root))
    failures.extend(_verify_public_security_posture(root))
    failures.extend(_verify_m167_session_logging_spine(root))
    failures.extend(_verify_m167_live_model_evidence_matrix(root))
    failures.extend(_verify_local_model_e2e_smoke_harness(root))
    failures.extend(_verify_performance_baseline_harness(root))
    failures.extend(_verify_release_verification_lanes(root))
    failures.extend(_verify_release_evidence_packet(root))
